import java.sql.*;
import java.util.logging.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.apache.commons.codec.binary.Base64;

public class ReportServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Custom input sanitizer - strips common attack patterns
    private String sanitizeInput(String input) {
        if (input == null) return null;
        // Remove null bytes
        input = input.replace("\0", "");
        // Limit length
        if (input.length() > 512) input = input.substring(0, 512);
        // Strip HTML tags for XSS prevention
        input = input.replaceAll("<[^>]*>", "");
        return input;
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        reportType = sanitizeInput(reportType);
        dateRange = sanitizeInput(dateRange);
        department = sanitizeInput(department);
        sortCol = sanitizeInput(sortCol);

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate report type against whitelist
        if (!reportType.matches("^(summary|detail|audit|compliance)$")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (!dateRange.matches("^\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}$")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        String[] dates = dateRange.split("_");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String query = "SELECT id, employee_name, department, amount, created_at " +
                          "FROM expense_reports " +
                          "WHERE report_type = '" + reportType + "' " +
                          "AND created_at BETWEEN ? AND ? ";

            if (department != null && !department.isEmpty()) {
                query += "AND department = '" + department + "' ";
            }

            if (sortCol != null && !sortCol.isEmpty()) {
                query += "ORDER BY " + sortCol;
            } else {
                query += "ORDER BY created_at DESC";
            }

            logger.info("Executing report query for type=" + reportType);

            PreparedStatement stmt = conn.prepareStatement(query);
            stmt.setString(1, dates[0]);
            stmt.setString(2, dates[1]);

            ResultSet rs = stmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{\"results\":[");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.printf("{\"id\":%d,\"name\":\"%s\",\"dept\":\"%s\",\"amount\":%.2f}",
                    rs.getInt("id"),
                    rs.getString("employee_name"),
                    rs.getString("department"),
                    rs.getDouble("amount"));
                first = false;
            }
            out.print("]}");

        } catch (SQLException e) {
            logger.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal server error");
        }
    }
}
